// Map the form fields to the Routewise lead shape and prepare the exact string that will be signed.
const f = $input.first().json.body ?? {};
const yes = (v) => v === true || ['true', 'yes', 'on', '1'].includes(String(v).toLowerCase());

const payload = {
  name: f.name,
  email: f.email,
  phone: f.phone,
  company: f.company,
  job_title: f.job_title ?? f.title,
  country: f.country,
  message: f.message,
  consent: f.consent === undefined ? undefined : yes(f.consent),
  // A stable id makes retries safe: Routewise returns the same lead instead of creating a second one.
  external_id: f.submission_id ?? `n8n-${$execution.id}`,
};
for (const k of Object.keys(payload)) if (payload[k] === undefined || payload[k] === '') delete payload[k];

const body = JSON.stringify(payload);
const t = Math.floor(Date.now() / 1000);
return [{ json: { body, t, toSign: `${t}.${body}` } }];
